    /// <summary>Upstream <c>re_get_xid_start</c>.</summary>
    internal static uint GetXidStart(uint codepoint)
    {
        uint field_2;
        uint field_1;
        uint field_0;
        uint offset;
        uint v;

        field_2 = codepoint >> 10;
        field_1 = (codepoint >> 5) & 0x1F;
        field_0 = (codepoint >> 3) & 0x3;
        offset = codepoint & 0x7;

        v = XidStartTable1[(int)field_2];
        v = XidStartTable2[(int)((v << 5) | field_1)];
        v = XidStartTable3[(int)((v << 2) | field_0)];

        return (v >> (int)offset) & 0x1;
    }


